async (page) => {
 const results=[];const check=(ok,label)=>{if(!ok)throw Error(label);results.push(label)};
 await page.evaluate(()=>{const data=JSON.parse(localStorage.getItem('workstation-interaction-v3'));const p=data.projects.find(p=>p.id==='studio');data.directory=[];for(let n=4;n<250;n++){const id='person-'+n;data.directory.push({id,name:'Collaborator '+String(n).padStart(3,'0'),role:n%5===0?'Guest':'Member'});p.members.push(id)}p.agents=Array.from({length:40},(_,n)=>({id:'agent-'+n,name:n===0?'Project agent':'Research agent '+n,retired:n%7===0}));localStorage.setItem('workstation-interaction-v3',JSON.stringify(data))});
 await page.reload();
 await page.getByRole('button',{name:'Studio',exact:true}).click();
 await page.getByRole('button',{name:'Add a component',exact:true}).click();
 await page.getByRole('button',{name:'Project',exact:true}).click();
 await page.getByRole('button',{name:'People',exact:true}).click();
 check(await page.locator('.directory-row').count()===24,'250-person directory renders one bounded page');
 check((await page.locator('.directory-footer').innerText()).includes('1–24 of 250'),'People pagination reports the actual result range');
 check(!/members|agent|Project context|250/.test(await page.locator('#rail').innerText()),'Rail contains navigation, not project-management prose or membership totals');
 await page.getByRole('button',{name:'Next results',exact:true}).click();
 check((await page.locator('.directory-footer').innerText()).includes('25–48 of 250'),'People pagination advances');
 await page.getByRole('textbox',{name:'Search people',exact:true}).fill('Collaborator 049');
 check(await page.locator('.directory-row').count()===1,'People search works across the whole directory');
 await page.getByRole('button',{name:'Agents',exact:true}).click();
 check(await page.locator('.directory-row').count()===24,'40-agent directory is paginated independently');
 await page.getByRole('button',{name:'Next results',exact:true}).click();
 check((await page.locator('.directory-footer').innerText()).includes('25–40 of 40'),'Agent pagination reaches later assignments');
 await page.getByRole('combobox',{name:'Filter agents',exact:true}).selectOption('retired');
 check(await page.locator('.directory-row').count()===6,'Agent filtering works without changing the rail');
 check(await page.locator('.module').first().evaluate(e=>parseFloat(getComputedStyle(e).borderRadius))<=2,'Modules no longer use rounded-square card styling');
 await page.getByRole('button',{name:'My workspace',exact:true}).click();
 const importFile=async filename=>{await page.getByRole('button',{name:'Add a component',exact:true}).click();const fixture=await page.request.get(page.url().split(/[?#]/)[0].replace(/[^/]*$/, '')+'tests/fixtures/'+filename);if(!fixture.ok())throw Error('Fixture unavailable: '+filename);await page.locator('#composer-import').setInputFiles({name:filename,mimeType:'application/octet-stream',buffer:await fixture.body()});await page.getByRole('button',{name:'Close '+filename,exact:true}).waitFor()};
 await importFile('project-brief.docx');
 check((await page.locator('.document-page').last().innerText()).includes('Project brief'),'Real DOCX content is rendered on a reading page');
 check(await page.locator('.document-page table').count()===1,'DOCX tables survive import');
 check(await page.locator('.document-page textarea').count()===0,'Imported document preview is not a generic textarea');
 await page.getByRole('button',{name:'Close project-brief.docx',exact:true}).click();
 await importFile('working-plan.xlsx');
 check((await page.getByRole('gridcell',{name:'B5',exact:true}).innerText())==='54','Real XLSX formula cells calculate from imported values');
 await page.getByRole('gridcell',{name:'B2',exact:true}).click();
 await page.getByRole('textbox',{name:'Formula bar',exact:true}).fill('20');
 await page.getByRole('textbox',{name:'Formula bar',exact:true}).press('Enter');
 check((await page.getByRole('gridcell',{name:'B5',exact:true}).innerText())==='62','Editing an imported workbook cell recalculates dependent formulas');
 await page.getByRole('button',{name:'Assumptions',exact:true}).click();
 check((await page.getByRole('gridcell',{name:'A2',exact:true}).innerText())==='Working days','Worksheet tabs show distinct sheet contents');
 await page.getByRole('button',{name:'Close working-plan.xlsx',exact:true}).click();
 await importFile('project-review.pptx');
 check(await page.locator('.slide-thumbnail').count()===3,'Real PPTX imports expose slide thumbnails');
 check((await page.locator('.slide-display').innerText()).includes('Project review'),'First imported slide renders its actual text');
 await page.getByRole('button',{name:'Next slide',exact:true}).click();
 check((await page.locator('.slide-display').innerText()).includes('One shared context'),'Slide navigation changes the actual slide');
 const ratio=await page.locator('.slide-viewport').evaluate(el=>{const b=el.getBoundingClientRect();return b.width/b.height});
 check(Math.abs(ratio-16/9)<.02,'Slide viewport preserves the source aspect ratio');
 await page.getByRole('button',{name:'Close project-review.pptx',exact:true}).click();
 await page.getByRole('button',{name:'Context graph',exact:true}).click();
 await page.locator('[data-node="resources:private"]').press('Enter');
 check(await page.locator('.graph-node .node-shape').count()===0,'Graph no longer renders bordered icon tiles');
 check(await page.locator('.graph-node .paper-mark').count()>0&&await page.locator('.graph-node .cell-mark').count()>0&&await page.locator('.graph-node .deck-mark').count()>0,'Graph distinguishes document, workbook and presentation content silhouettes');
 await page.locator('.graph-node').filter({hasText:'working-plan.xlsx'}).press('Enter');
 check(await page.locator('body').getAttribute('class')==='graph-mode'&&await page.locator('.sheet-viewer').count()===1,'Typed workbook inspection stays in the graph');
 check(await page.getByRole('button',{name:/Physics/}).count()===0,'Physics remains always on');
 return results;
}
